// The database files of the golden scenarios of fixtures/unit-store-scenarios.json,
// written by the Rust `DoubletsStorage<usize | u32, FileMappedUnitStore<_>>`
// (rust/examples/unit_store_trace.rs, regenerated by
// experiments/issue-111/unit-store-fixtures.mjs): replayed through `DoubletsStorage`,
// every scenario prints the same lines and leaves the same bytes. The
// fixtures hold the files without their trailing zeros.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, it } from 'node:test';

import { scratchDirectory } from './helpers/storage.mjs';
import { trace } from './helpers/unit-store-trace.mjs';

const FIXTURES = new URL('./fixtures/', import.meta.url);
const scenarios = JSON.parse(readFileSync(new URL('unit-store-scenarios.json', FIXTURES), 'utf8'));

describe('the Rust unit store files', () => {
  for (const { name, flags, script, initial, output, length } of scenarios) {
    it(`are written by the scenario ${name}`, () => {
      const database = join(scratchDirectory(), 'db.links');
      if (initial !== undefined) writeFileSync(database, Buffer.from(initial, 'hex'));
      const lines = trace(database, script, {
        resolved: flags.includes('--resolved'),
        u32: flags.includes('--u32'),
      });
      assert.deepEqual(lines, output);
      const bytes = readFileSync(database);
      const expected = readFileSync(new URL(`unit-store-${name}.links`, FIXTURES));
      assert.equal(bytes.length, length);
      assert.ok(bytes.subarray(0, expected.length).equals(expected), 'the links differ');
      const rest = bytes.subarray(expected.length);
      assert.ok(rest.equals(Buffer.alloc(rest.length)), 'the file holds more than the links');
    });
  }

  it('cover both address types, the resolvers and a partial first item', () => {
    assert.deepEqual(
      scenarios.map(({ name }) => name),
      [
        'u64-basic',
        'u32-basic',
        'u64-resolved',
        'u32-resolved',
        'u64-random',
        'u32-resolved-random',
        'u64-partial',
      ],
    );
  });
});
